/**
 * The frame rule and the exit builder of an ejected project's portals (ADR 0077 D2, D6, D9), in
 * `<package>/portal/`: copies of the runtime's `PortalFrame` and `ExitPortals`
 * (`engine-mod/src/main/java/dev/mcsupermods/runtime/registry/portal/`, Minecraft 26.3, Mojang
 * names), unchanged but for the package. The generator's tests compare every code line with the
 * runtime's.
 *
 * @packageDocumentation
 */

/** The source of `PortalFrame.java`, copied from the runtime's `PortalFrame`. */
export function portalFrameJava(portalPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's PortalFrame.
package ${portalPackage};

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.function.Predicate;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.tags.BlockTags;
import net.minecraft.util.BlockUtil;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;

/**
 * The frame rule of ADR 0077 D2, written from the ADR: a vertical rectangle on axis x or z whose inside is
 * {@value #MIN_WIDTH} to {@value #MAX_WIDTH} blocks wide and {@value #MIN_HEIGHT} to {@value #MAX_HEIGHT} high, with
 * frame blocks along all four sides (corners are never read) and only air, {@code #minecraft:fire} or the portal's own
 * block inside. The frame test is a predicate, so a tag frame is read at use time and follows {@code /reload}.
 */
public final class PortalFrame {
    public static final int MIN_WIDTH = 2;
    public static final int MAX_WIDTH = 21;
    public static final int MIN_HEIGHT = 3;
    public static final int MAX_HEIGHT = 21;

    /**
     * The flags {@link #fill} sets portal blocks with: {@code UPDATE_CLIENTS | UPDATE_KNOWN_SHAPE} (18), the flags vanilla
     * fills its own portal with (read with {@code javap -c} on 26.3 and 26.4-snapshot-7): clients are told, but no
     * neighbour or shape update runs while the inside fills, so a half-filled portal never breaks itself.
     */
    public static final int FILL_FLAGS = Block.UPDATE_CLIENTS | Block.UPDATE_KNOWN_SHAPE;

    private PortalFrame() {}

    /**
     * The inside of a frame: {@code min} is the lowest inside block (lowest y, and lowest x for axis x or lowest z for
     * axis z); {@code width} runs along {@code axis}, {@code height} upwards.
     */
    public record Rectangle(BlockPos min, Direction.Axis axis, int width, int height) {
        public Rectangle {
            min = min.immutable();
            if (axis == Direction.Axis.Y) {
                throw new IllegalArgumentException("a portal rectangle is vertical: axis x or z");
            }
        }

        /** The direction {@code width} runs in (east for x, south for z). */
        public Direction along() {
            return PortalFrame.along(axis);
        }

        /** The inside block {@code right} blocks along the axis and {@code up} blocks above {@link #min}. */
        public BlockPos at(int right, int up) {
            return min.relative(along(), right).above(up);
        }

        /** The highest inside block, opposite {@link #min}. */
        public BlockPos max() {
            return at(width - 1, height - 1);
        }

        /** Whether {@code pos} is inside the rectangle. */
        public boolean contains(BlockPos pos) {
            BlockPos max = max();
            return pos.getX() >= min.getX() && pos.getX() <= max.getX() && pos.getY() >= min.getY() && pos.getY() <= max.getY()
                    && pos.getZ() >= min.getZ() && pos.getZ() <= max.getZ();
        }

        /** Every inside position, bottom row first. */
        public List<BlockPos> positions() {
            List<BlockPos> out = new ArrayList<>(width * height);
            for (int up = 0; up < height; up++) {
                for (int right = 0; right < width; right++) {
                    out.add(at(right, up));
                }
            }
            return out;
        }

        /** The same rectangle as vanilla's {@code BlockUtil.FoundRectangle} (axis 1 = width, axis 2 = height). */
        public BlockUtil.FoundRectangle foundRectangle() {
            return new BlockUtil.FoundRectangle(min, width, height);
        }
    }

    /** The positive horizontal direction of a portal axis. */
    public static Direction along(Direction.Axis axis) {
        return axis == Direction.Axis.X ? Direction.EAST : Direction.SOUTH;
    }

    /** What may stand inside a frame (D2): air, a block in {@code #minecraft:fire}, or the portal's own block. */
    public static boolean isEmpty(BlockState state, Block portal) {
        return state.isAir() || state.is(BlockTags.FIRE) || state.is(portal);
    }

    /** {@link #find(LevelAccessor, BlockPos, Direction.Axis, Predicate, Block)} on axis x, then axis z. */
    public static Optional<Rectangle> find(LevelAccessor level, BlockPos inside, Predicate<BlockState> isFrame, Block portal) {
        Optional<Rectangle> x = find(level, inside, Direction.Axis.X, isFrame, portal);
        return x.isPresent() ? x : find(level, inside, Direction.Axis.Z, isFrame, portal);
    }

    /**
     * The frame around {@code inside} on {@code axis}, when the rule of D2 holds: from {@code inside} down to the bottom
     * frame, then along the bottom row to both side frames, then row by row up to a row that is frame all the way across.
     * Empty when {@code inside} is not empty, a side or the bottom or top is missing, a block stands inside, or a size
     * is outside {@value #MIN_WIDTH}..{@value #MAX_WIDTH} by {@value #MIN_HEIGHT}..{@value #MAX_HEIGHT}.
     */
    public static Optional<Rectangle> find(LevelAccessor level, BlockPos inside, Direction.Axis axis, Predicate<BlockState> isFrame,
            Block portal) {
        if (axis == Direction.Axis.Y || !isEmpty(level.getBlockState(inside), portal)) {
            return Optional.empty();
        }
        Direction right = along(axis);
        Direction left = right.getOpposite();

        // Down to the bottom frame.
        int below = 1;
        BlockState state = level.getBlockState(inside.below(below));
        while (isEmpty(state, portal)) {
            if (below >= MAX_HEIGHT) {
                return Optional.empty();
            }
            below++;
            state = level.getBlockState(inside.below(below));
        }
        if (!isFrame.test(state)) {
            return Optional.empty();
        }
        BlockPos bottom = inside.below(below - 1);

        // Along the bottom row to the left frame.
        int back = 0;
        state = level.getBlockState(bottom.relative(left, 1));
        while (isEmpty(state, portal)) {
            back++;
            if (back >= MAX_WIDTH) {
                return Optional.empty();
            }
            state = level.getBlockState(bottom.relative(left, back + 1));
        }
        if (!isFrame.test(state)) {
            return Optional.empty();
        }
        BlockPos min = bottom.relative(left, back);

        // From the left frame to the right frame.
        int width = 1;
        state = level.getBlockState(min.relative(right, width));
        while (isEmpty(state, portal)) {
            width++;
            if (width > MAX_WIDTH) {
                return Optional.empty();
            }
            state = level.getBlockState(min.relative(right, width));
        }
        if (!isFrame.test(state) || width < MIN_WIDTH) {
            return Optional.empty();
        }

        // The bottom frame under every inside column.
        for (int i = 0; i < width; i++) {
            if (!isFrame.test(level.getBlockState(min.relative(right, i).below()))) {
                return Optional.empty();
            }
        }

        // Rows upwards until one is frame all the way across (the top).
        int height = 0;
        while (true) {
            BlockPos row = min.above(height);
            if (height >= MIN_HEIGHT && rowIsFrame(level, row, right, width, isFrame)) {
                return Optional.of(new Rectangle(min, axis, width, height));
            }
            if (height >= MAX_HEIGHT) {
                return Optional.empty();
            }
            if (!isFrame.test(level.getBlockState(row.relative(left))) || !isFrame.test(level.getBlockState(row.relative(right, width)))) {
                return Optional.empty();
            }
            for (int i = 0; i < width; i++) {
                if (!isEmpty(level.getBlockState(row.relative(right, i)), portal)) {
                    return Optional.empty();
                }
            }
            height++;
        }
    }

    private static boolean rowIsFrame(LevelAccessor level, BlockPos row, Direction right, int width, Predicate<BlockState> isFrame) {
        for (int i = 0; i < width; i++) {
            if (!isFrame.test(level.getBlockState(row.relative(right, i)))) {
                return false;
            }
        }
        return true;
    }

    /** Whether the whole inside is {@code portal} (a lit portal). */
    public static boolean isComplete(LevelAccessor level, Rectangle rectangle, Block portal) {
        for (BlockPos pos : rectangle.positions()) {
            if (!level.getBlockState(pos).is(portal)) {
                return false;
            }
        }
        return true;
    }

    /** Whether the inside holds no {@code portal} block yet (a frame that can be lit). */
    public static boolean isUnlit(LevelAccessor level, Rectangle rectangle, Block portal) {
        for (BlockPos pos : rectangle.positions()) {
            if (level.getBlockState(pos).is(portal)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Fills the inside with {@code portalState}, its {@code axis} property set to the rectangle's axis when the state has
     * one ({@code BlockStateProperties.HORIZONTAL_AXIS}), with {@link #FILL_FLAGS}.
     */
    public static void fill(LevelAccessor level, Rectangle rectangle, BlockState portalState) {
        BlockState state = portalState.hasProperty(BlockStateProperties.HORIZONTAL_AXIS)
                ? portalState.setValue(BlockStateProperties.HORIZONTAL_AXIS, rectangle.axis())
                : portalState;
        for (BlockPos pos : rectangle.positions()) {
            level.setBlock(pos, state, FILL_FLAGS);
        }
    }
}
`;
}

/** The source of `ExitPortals.java`, copied from the runtime's `ExitPortals`. */
export function exitPortalsJava(portalPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's ExitPortals.
package ${portalPackage};

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;

/**
 * Exit portals for {@code arrival: portal} (ADR 0077 D6), written from the ADR, never from vanilla's {@code PortalForcer}:
 * the nearest indexed portal of the same block within the caller's radius; else a new exit with a
 * {@value #EXIT_WIDTH} by {@value #EXIT_HEIGHT} inside built on the closest build site within {@value #BUILD_SEARCH}
 * blocks (x and z) of the target, between the level's lowest y and the top of its logical height; else a forced build at
 * the target on a platform of the frame block with the space around the inside cleared. A built exit is indexed.
 *
 * <p>A build site for an inside whose lowest block is {@code p}: the whole frame (four columns along the axis, five
 * rows from {@code p.below()} to {@code p.above(3)}) fits in blocks that can be replaced and hold no fluid, the four
 * blocks under the frame are sturdy on top, and the two blocks on each side of the bottom two inside rows (where a
 * traveller steps out) are free the same way. The closest site to the target wins (squared distance; on a tie the column nearer in x and z, then the lower y);
 * the entry's axis is tried first, then the other one.
 */
public final class ExitPortals {
    /** How far (x and z) from the target a build site is looked for. */
    public static final int BUILD_SEARCH = 16;
    public static final int EXIT_WIDTH = 2;
    public static final int EXIT_HEIGHT = 3;
    /** Frame, platform and cleared blocks are set with {@code Block.UPDATE_ALL}; the inside with {@link PortalFrame#FILL_FLAGS}. */
    public static final int BUILD_FLAGS = Block.UPDATE_ALL;

    private ExitPortals() {}

    /** The highest y a block may take in the level: the top of its logical height, at most its build height. */
    public static int topY(ServerLevel level) {
        return Math.min(level.getMaxY(), level.getMinY() + level.getLogicalHeight() - 1);
    }

    /**
     * The exit for a traveller arriving near {@code target}: the nearest indexed portal of {@code portal} within the square
     * {@code radius} (stale entries dropped), else a new one ({@link #build}). {@code target} is first clamped to the world
     * border.
     */
    public static PortalFrame.Rectangle findOrBuild(ServerLevel level, BlockPos target, Direction.Axis axis, Block portal, BlockState frame,
            int radius) {
        BlockPos clamped = clampToBorder(level, target);
        Optional<PortalIndex.Entry> existing = PortalIndexAttachment.nearest(level, PortalIndexAttachment.id(portal), clamped, radius);
        return existing.map(PortalIndex.Entry::rectangle).orElseGet(() -> build(level, clamped, axis, portal, frame));
    }

    /**
     * Builds and indexes a new exit near {@code target}: on the closest build site ({@link #findSite}, the given axis
     * first), else forced at the target ({@link #forceBuild}).
     */
    public static PortalFrame.Rectangle build(ServerLevel level, BlockPos target, Direction.Axis axis, Block portal, BlockState frame) {
        BlockPos clamped = clampToBorder(level, target);
        Direction.Axis other = axis == Direction.Axis.X ? Direction.Axis.Z : Direction.Axis.X;
        Optional<PortalFrame.Rectangle> site = findSite(level, clamped, axis);
        if (site.isEmpty()) {
            site = findSite(level, clamped, other);
        }
        if (site.isEmpty()) {
            return forceBuild(level, clamped, axis, portal, frame);
        }
        PortalFrame.Rectangle rectangle = site.get();
        placeFrame(level, rectangle, frame);
        PortalFrame.fill(level, rectangle, portal.defaultBlockState());
        PortalIndexAttachment.add(level, portal, rectangle);
        return rectangle;
    }

    /**
     * The closest build site for an exit on {@code axis} within {@value #BUILD_SEARCH} blocks (x and z) of {@code target},
     * as a {@value #EXIT_WIDTH} by {@value #EXIT_HEIGHT} rectangle, or empty.
     */
    public static Optional<PortalFrame.Rectangle> findSite(ServerLevel level, BlockPos target, Direction.Axis axis) {
        int lowest = level.getMinY() + 2;
        int highest = topY(level) - EXIT_HEIGHT;
        if (lowest > highest) {
            return Optional.empty();
        }
        List<int[]> columns = new ArrayList<>();
        for (int dx = -BUILD_SEARCH; dx <= BUILD_SEARCH; dx++) {
            for (int dz = -BUILD_SEARCH; dz <= BUILD_SEARCH; dz++) {
                columns.add(new int[] {dx, dz});
            }
        }
        columns.sort(Comparator.comparingInt((int[] c) -> c[0] * c[0] + c[1] * c[1]).thenComparingInt(c -> c[0]).thenComparingInt(c -> c[1]));
        long best = Long.MAX_VALUE;
        BlockPos bestPos = null;
        BlockPos.MutableBlockPos p = new BlockPos.MutableBlockPos();
        for (int[] c : columns) {
            long flat = (long) c[0] * c[0] + (long) c[1] * c[1];
            if (flat > best) {
                break;
            }
            for (int y = lowest; y <= highest; y++) {
                long dy = y - target.getY();
                long distance = flat + dy * dy;
                if (distance >= best) {
                    if (y > target.getY()) {
                        break;
                    }
                    continue;
                }
                p.set(target.getX() + c[0], y, target.getZ() + c[1]);
                if (isSite(level, p, axis)) {
                    best = distance;
                    bestPos = p.immutable();
                }
            }
        }
        return bestPos == null ? Optional.empty() : Optional.of(new PortalFrame.Rectangle(bestPos, axis, EXIT_WIDTH, EXIT_HEIGHT));
    }

    /** Whether an exit with its lowest inside block at {@code min} on {@code axis} can be built there (see the class). */
    public static boolean isSite(ServerLevel level, BlockPos min, Direction.Axis axis) {
        Direction right = PortalFrame.along(axis);
        // Cheap rejections first: sturdy ground under the first frame column, free space for its bottom frame block.
        for (int i = -1; i <= EXIT_WIDTH; i++) {
            BlockPos column = min.relative(right, i);
            BlockPos ground = column.below(2);
            if (!level.getBlockState(ground).isFaceSturdy(level, ground, Direction.UP) || !isFree(level, column.below())) {
                return false;
            }
        }
        for (int i = -1; i <= EXIT_WIDTH; i++) {
            BlockPos column = min.relative(right, i);
            for (int up = 0; up <= EXIT_HEIGHT; up++) {
                if (!isFree(level, column.above(up))) {
                    return false;
                }
            }
        }
        Direction side = right.getClockWise();
        for (int i = 0; i < EXIT_WIDTH; i++) {
            for (int up = 0; up < 2; up++) {
                BlockPos inside = min.relative(right, i).above(up);
                if (!isFree(level, inside.relative(side)) || !isFree(level, inside.relative(side.getOpposite()))) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isFree(ServerLevel level, BlockPos pos) {
        BlockState state = level.getBlockState(pos);
        return state.canBeReplaced() && state.getFluidState().isEmpty();
    }

    /**
     * Builds and indexes an exit with its lowest inside block at {@code target} (y kept between the level's lowest y and
     * the top of its logical height): a platform of {@code frame} three blocks across under the frame, the blocks on both
     * sides of the inside cleared to air, the frame with its corners, and the inside filled with {@code portal}.
     */
    public static PortalFrame.Rectangle forceBuild(ServerLevel level, BlockPos target, Direction.Axis axis, Block portal, BlockState frame) {
        int y = Math.max(level.getMinY() + 1, Math.min(topY(level) - EXIT_HEIGHT, target.getY()));
        PortalFrame.Rectangle rectangle = new PortalFrame.Rectangle(new BlockPos(target.getX(), y, target.getZ()), axis, EXIT_WIDTH, EXIT_HEIGHT);
        Direction right = rectangle.along();
        Direction side = right.getClockWise();
        BlockState air = Blocks.AIR.defaultBlockState();
        for (int i = -1; i <= EXIT_WIDTH; i++) {
            for (int s = -1; s <= 1; s++) {
                level.setBlock(rectangle.at(i, -1).relative(side, s), frame, BUILD_FLAGS);
            }
        }
        for (int i = 0; i < EXIT_WIDTH; i++) {
            for (int up = 0; up < EXIT_HEIGHT; up++) {
                BlockPos inside = rectangle.at(i, up);
                level.setBlock(inside.relative(side), air, BUILD_FLAGS);
                level.setBlock(inside.relative(side.getOpposite()), air, BUILD_FLAGS);
            }
        }
        placeFrame(level, rectangle, frame);
        PortalFrame.fill(level, rectangle, portal.defaultBlockState());
        PortalIndexAttachment.add(level, portal, rectangle);
        return rectangle;
    }

    /** The frame around {@code rectangle}, corners included. */
    private static void placeFrame(ServerLevel level, PortalFrame.Rectangle rectangle, BlockState frame) {
        for (int i = -1; i <= rectangle.width(); i++) {
            level.setBlock(rectangle.at(i, -1), frame, BUILD_FLAGS);
            level.setBlock(rectangle.at(i, rectangle.height()), frame, BUILD_FLAGS);
        }
        for (int up = 0; up < rectangle.height(); up++) {
            level.setBlock(rectangle.at(-1, up), frame, BUILD_FLAGS);
            level.setBlock(rectangle.at(rectangle.width(), up), frame, BUILD_FLAGS);
        }
    }

    private static BlockPos clampToBorder(ServerLevel level, BlockPos target) {
        BlockPos clamped = level.getWorldBorder().clampToBounds(target.getX(), target.getY(), target.getZ());
        return new BlockPos(clamped.getX(), target.getY(), clamped.getZ());
    }
}
`;
}
